const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-thumbnailer-backfill", node: "Code: Init Run" } });

// Reset per-run counters at the START (workflow static data persists across
// executions — a run that crashed before Code: Build Summary must not carry
// stale counts into the next run's summary).
const staticData = $getWorkflowStaticData('global');
staticData.processed = 0;
staticData.failed = 0;
staticData.skipped_no_source = 0;

// Read time_limit_seconds from the ORIGINAL webhook payload by node name — the
// upstream lock node returns a fresh object without body/query (the PROJ-92 bug).
let body = {}, query = {};
try {
  const webhookItem = $('Webhook: POST /thumb-backfill').first().json;
  body = webhookItem.body || {};
  query = webhookItem.query || {};
} catch(e) {}
const rawLimit = body.time_limit_seconds !== undefined ? body.time_limit_seconds : query.time_limit_seconds;
const parsedLimit = parseInt(rawLimit, 10);
const maxRuntimeSeconds = (!isNaN(parsedLimit) && parsedLimit > 0) ? parsedLimit : null;

const COLLECTIONS = ['Invoice', 'BankStatement', 'BankTransaction', 'Document', 'Email', 'SecuritySettlement', 'Contract', 'Image'];
const LIMIT = 100;

const lockOwner = $('Code: Acquire Backfill Lock').first().json.lock_owner;

logger.info(`[thumb-backfill] Init: max_runtime_seconds=${maxRuntimeSeconds === null ? 'none' : maxRuntimeSeconds}`);
return [{ json: { collections: COLLECTIONS, limit: LIMIT, window_start: Date.now(), max_runtime_seconds: maxRuntimeSeconds, lock_owner: lockOwner } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-thumbnailer-backfill", node: "Code: Query Weaviate (no thumbnail)" } });
const axios = require('axios');
const run = $input.first().json;
const { collections, limit } = run;
const WEAVIATE = 'http://weaviate:8080';
const LIMIT = limit || 100;

// Per-collection field sets. Email and BankTransaction have no path field in
// their Weaviate schema — asking for filePath/fileHash there returns a GraphQL
// error and the whole collection would be silently skipped (the bug PROJ-95
// fixes). Instead we fetch the fields each render mode actually needs.
// thumbnail_path itself may not exist yet on a class that has never had a
// thumbnail (e.g. BankTransaction on first run — Weaviate auto-schema only
// adds it on the first PATCH) — so it is requested separately and dropped on
// a GraphQL 'Cannot query field' error (every returned object is then a
// no-thumbnail hit by definition).
const CORE_FIELDS = {
  Image: '_additional { id } file_path file_hash',
  Email: '_additional { id } subject content',
  BankTransaction: '_additional { id } amount currency direction counterparty purpose transactionDate bankName accountIban'
};
function coreFieldsFor(collection) {
  return CORE_FIELDS[collection] || '_additional { id } filePath fileHash';
}

function isMissingFieldError(errors, field) {
  try {
    const s = JSON.stringify(errors);
    return s.includes('Cannot query field') && s.includes(field);
  } catch(e) { return false; }
}

const allDocs = [];

for (const collection of collections) {
  let cursor = null;
  const isImage = collection === 'Image';
  const pathField = isImage ? 'file_path' : 'filePath';
  let includeThumbField = true; // becomes false if the class has no thumbnail_path yet

  while (true) {
    const cursorClause = cursor ? `, after: "${cursor}"` : '';
    const thumbClause = includeThumbField ? ' thumbnail_path' : '';
    const gql = `{ Get { ${collection}(limit: ${LIMIT}${cursorClause}) { ${coreFieldsFor(collection)}${thumbClause} } } }`;

    let results;
    try {
      const r = await axios.post(`${WEAVIATE}/v1/graphql`, { query: gql }, {
        headers: { 'Content-Type': 'application/json' },
        timeout: 30000
      });
      if (r.data?.errors) {
        if (includeThumbField && isMissingFieldError(r.data.errors, 'thumbnail_path')) {
          logger.info(`[thumb-backfill] ${collection} has no thumbnail_path property yet — retrying query without it`);
          includeThumbField = false;
          continue; // retry same page without the thumbnail_path field
        }
        logger.warn(`[thumb-backfill] GraphQL error for ${collection}: ${JSON.stringify(r.data.errors)}`);
        break;
      }
      results = r.data?.data?.Get?.[collection] || [];
    } catch(e) {
      logger.warn(`[thumb-backfill] Request failed for ${collection}: ${e.message}`);
      break;
    }

    if (results.length === 0) break;

    for (const doc of results) {
      if (includeThumbField && doc.thumbnail_path) continue;
      const entry = {
        weaviate_uuid: doc._additional?.id,
        document_type: collection,
        file_path: doc[pathField] || null
      };
      if (collection === 'Email') {
        entry.subject = doc.subject || '';
        entry.content = doc.content || '';
      } else if (collection === 'BankTransaction') {
        entry.amount = doc.amount;
        entry.currency = doc.currency || null;
        entry.direction = doc.direction || null;
        entry.counterparty = doc.counterparty || null;
        entry.purpose = doc.purpose || null;
        entry.transactionDate = doc.transactionDate || null;
        entry.bankName = doc.bankName || null;
        entry.accountIban = doc.accountIban || null;
      }
      allDocs.push(entry);
    }

    if (results.length < LIMIT) break;
    cursor = results[results.length - 1]?._additional?.id;
    if (!cursor) break;
  }

  const collCount = allDocs.filter(d => d.document_type === collection).length;
  logger.info(`[thumb-backfill] ${collection}: found ${collCount} docs without thumbnail`);
}

const totalDocs = allDocs.length;
logger.info(`[thumb-backfill] Total docs to process: ${totalDocs}`);
if (totalDocs === 0) {
  return [{ json: { _empty: true, total_docs: 0, window_start: run.window_start, max_runtime_seconds: run.max_runtime_seconds, lock_owner: run.lock_owner } }];
}
return allDocs.map(d => ({ json: { ...d, _empty: false, total_docs: totalDocs, window_start: run.window_start, max_runtime_seconds: run.max_runtime_seconds, lock_owner: run.lock_owner } }));

const resp = $input.first().json;
const body = resp.body || resp;
const thumbPath = body.thumbnail_path || null;
const src = $('IF: Renderable').first().json;
const uuid = body.weaviate_uuid || src.weaviate_uuid || null;
const docType = body.document_type || src.document_type || 'Document';
if (!thumbPath || !uuid) {
  throw new Error('Missing thumbnail_path or uuid in response: ' + JSON.stringify(body));
}
return [{ json: { thumbnail_path: thumbPath, weaviate_uuid: uuid, document_type: docType } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-thumbnailer-backfill", node: "Code: Log PATCH Result" } });
const staticData = $getWorkflowStaticData('global');
const resp = $input.first().json;
const statusCode = resp.statusCode || 0;
if (statusCode >= 200 && statusCode < 300) {
  staticData.processed = (staticData.processed || 0) + 1;
  return [{ json: { result: 'processed' } }];
}
staticData.failed = (staticData.failed || 0) + 1;
logger.warn(`[thumb-backfill] PATCH failed (HTTP ${statusCode})`);
return [{ json: { result: 'failed', reason: 'weaviate_patch_failed' } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-thumbnailer-backfill", node: "Code: Log Generation Error" } });
const staticData = $getWorkflowStaticData('global');
staticData.failed = (staticData.failed || 0) + 1;
