const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-thumbnailer-backfill", node: "Code: Time Check" } });
// Runs once per document (after the in-flight doc is fully processed). Reads
// the window from Code: Init Run by node name.
const run = $('Code: Init Run').first().json;
const maxRuntime = run.max_runtime_seconds;
let timeLimitReached = false;
if (maxRuntime !== null && maxRuntime !== undefined) {
  const elapsed = (Date.now() - run.window_start) / 1000;
  timeLimitReached = elapsed >= maxRuntime;
  if (timeLimitReached) {
    logger.info(`[thumb-backfill] Time limit reached (elapsed=${Math.round(elapsed)}s, limit=${maxRuntime}s) — leaving loop, in-flight doc already done`);
  }
}
return [{ json: { _time_limit_reached: timeLimitReached } }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-thumbnailer-backfill", node: "Code: Build Summary" } });
const redis = require('redis');
const staticData = $getWorkflowStaticData('global');

const processed = staticData.processed || 0;
const failed = staticData.failed || 0;
const skipped_no_source = staticData.skipped_no_source || 0;

// Reset per-run counters for the next invocation (also reset at the start in
// Code: Init Run — belt and braces).
staticData.processed = 0;
staticData.failed = 0;
staticData.skipped_no_source = 0;

const run = $('Code: Init Run').first().json;
const stoppedByTime = (() => {
  if (run.max_runtime_seconds === null || run.max_runtime_seconds === undefined) return false;
  return ((Date.now() - run.window_start) / 1000) >= run.max_runtime_seconds;
})();

// remaining = entries of THIS run's flat list that were not reached (time
// limit) — a completed run always leaves 0. thumbnail_path is indexFilterable:
// false in every schema, so an IsNull aggregate is not possible; deriving it
// from the flat-list total is exact and cheaper. total_docs is 0 on the empty
// path (IF: Nothing To Do -> here), which correctly yields remaining 0.
let totalDocs = 0;
try {
  const first = $('Code: Query Weaviate (no thumbnail)').first().json;
  totalDocs = first.total_docs || 0;
} catch(e) {}
const touched = processed + failed + skipped_no_source;
const remaining = Math.max(0, totalDocs - touched);

// Release the lock (owner-checked) in every completion path.
const owner = run.lock_owner;
if (owner) {
  const RELEASE_SCRIPT = `local raw = redis.call('GET', KEYS[1]) if not raw then return 0 end local ok, data = pcall(cjson.decode, raw) if not ok or data.owner ~= ARGV[1] then return 0 end redis.call('DEL', KEYS[1]) return 1`;
  let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
  const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
  try {
    await client.connect();
    await client.eval(RELEASE_SCRIPT, { keys: ['alice:dms:processor:lock:run'], arguments: [owner] });
  } catch(e) {
    logger.info(`[thumb-backfill] Lock release error: ${e.message}`);
  } finally {
    await client.quit().catch(() => {});
  }
}

const stopped_reason = stoppedByTime ? 'time_limit' : 'completed';
const summary = { status: 'ok', stopped_reason, processed, failed, skipped_no_source, remaining };
logger.info(`[thumb-backfill] Summary: ${JSON.stringify(summary)}`);
return [{ json: summary }];
